function frame(now) {
  if (!session) return;
  if (previous === 0) previous = now;
  accumulator += Math.min(0.1, (now - previous) / 1000);
  previous = now;
  while (accumulator >= STEP) {
    session.update(STEP);
    accumulator -= STEP;
  }
  render();
  requestAnimationFrame(frame);
}

